BEGIN;
TRUNCATE public.integration_sync_health, public.integration_sync_events;
INSERT INTO public.integration_sync_health(component_key,recovery_enabled) VALUES('acculynx-worker',true);
CREATE FUNCTION pg_temp.assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF;END$$;
-- Historical partial-run fixtures must not affect these isolated monitor assertions.
UPDATE public.acculynx_sync_runs SET completed_at=now()-interval '2 days',status='completed';
SELECT public.observe_integration_sync('cron:test',now()-interval '5 minutes',false,'schema_error');
SELECT pg_temp.assert((SELECT count(*)=1 FROM public.integration_sync_events WHERE component_key='cron:test'),'first failure creates durable event');
SELECT public.observe_integration_sync('cron:test',now()-interval '5 minutes',false,'schema_error');
SELECT pg_temp.assert((SELECT consecutive_failures=1 FROM public.integration_sync_health WHERE component_key='cron:test'),'duplicate observation ignored');
SELECT public.observe_integration_sync('cron:test',now()-interval '4 minutes',false,'schema_error');
SELECT public.observe_integration_sync('cron:test',now()-interval '3 minutes',false,'schema_error');
SELECT pg_temp.assert((SELECT count(*)=2 FROM public.integration_sync_events WHERE component_key='cron:test'),'persistent failure escalation at three');
SELECT public.observe_integration_sync('cron:test',now()-interval '2 minutes',true,NULL);
SELECT pg_temp.assert((SELECT consecutive_failures=0 FROM public.integration_sync_health WHERE component_key='cron:test'),'success resets failure streak');
SELECT public.observe_integration_sync('acculynx-worker',now()-interval '10 minutes',false,'upstream_error','{"multiAccount":true}');
SELECT public.observe_integration_sync('acculynx-worker',now()-interval '9 minutes',false,'upstream_error','{"multiAccount":true}');
SELECT public.observe_integration_sync('acculynx-worker',now()-interval '8 minutes',false,'upstream_error','{"multiAccount":true}');
SELECT pg_temp.assert((SELECT recovery_attempts=1 FROM public.integration_sync_health WHERE component_key='acculynx-worker'),'bounded automatic recovery at three');
UPDATE public.acculynx_sync_runs SET status='completed',completed_at=now()-interval '2 days';
SELECT public.observe_integration_sync('acculynx-worker',now()-interval '7 minutes',false,'upstream_error','{"multiAccount":true}');
SELECT pg_temp.assert((SELECT recovery_attempts=1 FROM public.integration_sync_health WHERE component_key='acculynx-worker'),'recovery cooldown prevents repeated calls');
SELECT public.observe_integration_sync('acculynx-worker',now()-interval '6 minutes',false,'upstream_error','{"multiAccount":true}');
SELECT pg_temp.assert((SELECT consecutive_failures=5 AND recovery_attempts=1 FROM public.integration_sync_health WHERE component_key='acculynx-worker'),'fifth failure stops automatic attempts');
SELECT public.observe_integration_sync('acculynx-worker',now()-interval '5 minutes',true,NULL);
SELECT public.observe_integration_sync('acculynx-worker',now()-interval '4 minutes',false,'auth_denied','{"multiAccount":true}');
SELECT public.observe_integration_sync('acculynx-worker',now()-interval '3 minutes',false,'auth_denied','{"multiAccount":true}');
SELECT public.observe_integration_sync('acculynx-worker',now()-interval '2 minutes',false,'auth_denied','{"multiAccount":true}');
SELECT pg_temp.assert((SELECT recovery_attempts=0 FROM public.integration_sync_health WHERE component_key='acculynx-worker'),'authentication failures never auto-repaired');
INSERT INTO cron.job VALUES(1,'new-api-sync',true);
INSERT INTO cron.job_run_details VALUES(1,now()-interval '1 minute',now(),'failed','sensitive external data');
INSERT INTO public.runtime_job_runs VALUES('unregistered-mcp', 'failure', now());
SELECT public.monitor_integration_syncs();
SELECT pg_temp.assert((SELECT consecutive_failures=1 FROM public.integration_sync_health WHERE component_key='cron:new-api-sync'),'new scheduler job discovered automatically');
SELECT pg_temp.assert((SELECT consecutive_failures=1 FROM public.integration_sync_health WHERE component_key='runtime:unregistered-mcp'),'unregistered runtime failure discovered');
SELECT pg_temp.assert((SELECT count(*)=0 FROM public.integration_sync_events WHERE failure_code LIKE '%sensitive%'),'free-text excluded from telemetry');
SELECT pg_temp.assert(NOT has_function_privilege('authenticated','public.monitor_integration_syncs()','EXECUTE'),'public cannot operate monitor');
SELECT 'PASS: first failure, dedupe, threshold three, cooldown, stop at five, auth escalation, app-wide discovery';

ROLLBACK;
